import java.util.Scanner;

public class Main {

    static boolean contains(String s, String sub) {
        return s.contains(sub);
    }

    static boolean isServiceChosen(String text, String name) {
        String[] globalNeg = {"无附加项目", "无附加服务", "没有附加项目", "没有附加服务",
                "不要附加", "不加附加", "无需附加", "免附加", "取消附加"};
        for (String neg : globalNeg) {
            if (text.contains(neg)) {
                return false;
            }
        }

        int pos = text.indexOf(name);
        if (pos < 0) {
            return false;
        }

        String[] seps = {"，", ",", "。", ".", "；", ";", "！", "!", "？", "?", "、", " "};
        int start = 0;
        for (String sep : seps) {
            if (pos > 0) {
                int p = text.lastIndexOf(sep, pos - 1);
                if (p >= 0) {
                    int end = p + sep.length();
                    if (end > start) {
                        start = end;
                    }
                }
            }
        }

        String pre = text.substring(start, pos);
        String[] negWords = {"不", "无", "没", "未", "别", "免", "拒绝", "取消"};
        for (String w : negWords) {
            if (pre.contains(w)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();

        String carType;
        int base;
        if (s.contains("旗舰型")) {
            carType = "旗舰型";
            base = 78;
        } else if (s.contains("加强型")) {
            carType = "加强型";
            base = 58;
        } else {
            carType = "标准型";
            base = 38;
        }

        int afterType;
        if (s.contains("晶镀养护")) {
            afterType = (base * 5 + 1) / 2;
        } else if (s.contains("深度养护")) {
            afterType = (base * 9 + 4) / 5;
        } else {
            afterType = base;
        }

        boolean member;
        if (s.contains("非会员") || s.contains("不是会员")) {
            member = false;
        } else if (s.contains("会员")) {
            member = true;
        } else {
            member = false;
        }

        int washCost;
        if (member) {
            washCost = (afterType * 85) / 100;
        } else {
            washCost = afterType;
        }

        int addon = 0;
        if (isServiceChosen(s, "除尘维护")) {
            addon += 28;
        }
        if (isServiceChosen(s, "液路清理")) {
            addon += 45;
        }

        boolean holiday;
        if (s.contains("非节假日") || s.contains("不是节假日")) {
            holiday = false;
        } else if (s.contains("节假日")) {
            holiday = true;
        } else {
            holiday = false;
        }

        int beforeHoliday = washCost + addon;
        int afterHoliday;
        if (holiday) {
            afterHoliday = (beforeHoliday * 6 + 4) / 5;
        } else {
            afterHoliday = beforeHoliday;
        }

        int siteFee;
        if (s.contains("露天") || s.contains("非室内") || s.contains("不是室内")) {
            siteFee = 0;
        } else if (s.contains("室内")) {
            siteFee = 15;
        } else {
            siteFee = 0;
        }

        int totalBill = afterHoliday + siteFee;

        System.out.println("{\"total_bill\":" + totalBill +
                ",\"wash_cost\":" + washCost +
                ",\"car_type\":\"" + carType + "\"}");
    }
}
